result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fetchRetry.test.mjs", "content": "import test from 'node:test';
import assert from 'node:assert/strict';
import { fetchJsonWithRetry } from './fetchRetry.mjs';

// Programmable fetch stub driven by a queue of scripted outcomes.
// Outcomes are either an Error (rejects) or {status, json} (resolves).
function makeFetchStub(outcomes) {
  const calls = [];
  const fetchImpl = async (url) => {
    calls.push(url);
    const next = outcomes.shift();
    if (next instanceof Error) throw next;
    return {
      status: next.status,
      json: async () => next.json,
    };
  };
  return { fetchImpl, calls };
}

// Fake sleep: records requested delays, resolves immediately.
function makeSleep() {
  const delays = [];
  const sleep = async (ms) => {
    delays.push(ms);
  };
  return { sleep, delays };
}

test('success on first try: no sleeps', async () => {
  const { fetchImpl, calls } = makeFetchStub([{ status: 200, json: { hello: 'world' } }]);
  const { sleep, delays } = makeSleep();

  const result = await fetchJsonWithRetry('http://x/', { fetchImpl, sleep });

  assert.deepEqual(result, { ok: true, status: 200, data: { hello: 'world' } });
  assert.equal(calls.length, 1);
  assert.deepEqual(delays, []);
});

test('two 500s then 200: delays exactly [100, 200]', async () => {
  const { fetchImpl, calls } = makeFetchStub([
    new Error('server 500'),
    new Error('server 500'),
    { status: 200, json: ['ok'] },
  ]);
  const { sleep, delays } = makeSleep();

  const result = await fetchJsonWithRetry('http://x/', { fetchImpl, sleep, retries: 3, baseDelayMs: 100 });

  assert.deepEqual(result, { ok: true, status: 200, data: ['ok'] });
  assert.equal(calls.length, 3);
  assert.deepEqual(delays, [100, 200]);
});

test('404 returns ok:false without retrying', async () => {
  const { fetchImpl, calls } = makeFetchStub([{ status: 404, json: null }]);
  const { sleep, delays } = makeSleep();

  const result = await fetchJsonWithRetry('http://x/', { fetchImpl, sleep, retries: 3, baseDelayMs: 100 });

  assert.deepEqual(result, { ok: false, status: 404, data: null });
  assert.equal(calls.length, 1);
  assert.deepEqual(delays, []);
});

test('all attempts fail: rejects with last error, fetch called retries+1 times, delays [100, 200, 400]', async () => {
  const e1 = new Error('boom 1');
  const e2 = new Error('boom 2');
  const e3 = new Error('boom 3');
  const e4 = new Error('boom 4');
  const { fetchImpl, calls } = makeFetchStub([e1, e2, e3, e4]);
  const { sleep, delays } = makeSleep();

  await assert.rejects(
    fetchJsonWithRetry('http://x/', { fetchImpl, sleep, retries: 3, baseDelayMs: 100 }),
    (err) => err === e4
  );
  assert.equal(calls.length, 4); // retries + 1
  assert.deepEqual(delays, [100, 200, 400]);
});

test('network rejection then success', async () => {
  const networkErr = new Error('ECONNREFUSED');
  const { fetchImpl, calls } = makeFetchStub([networkErr, { status: 200, json: { recovered: true } }]);
  const { sleep, delays } = makeSleep();

  const result = await fetchJsonWithRetry('http://x/', { fetchImpl, sleep, baseDelayMs: 50 });

  assert.deepEqual(result, { ok: true, status: 200, data: { recovered: true } });
  assert.equal(calls.length, 2);
  assert.deepEqual(delays, [50]);
});
"})
print(result)
